import sys
import heapq

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))
    k = int(next(iterator))

    adj = [[] for _ in range(n + 1)]

    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        w = int(next(iterator))
        adj[u].append((v, w))
        adj[v].append((u, w))

    pq = []
    visited = [False] * (n + 1)
    count = 0
    result = 0

    for start_node in range(1, n + 1):
        dist = {start_node: 0}
        heap = [(0, start_node)]

        while heap:
            d, u = heapq.heappop(heap)

            if d > dist.get(u, float('inf')):
                continue

            if u != start_node:
                count += 1
                if count == k:
                    result = d
                    break

            if count >= k:
                break

            for v, w in adj[u]:
                new_dist = d + w
                if v not in dist or new_dist < dist[v]:
                    dist[v] = new_dist
                    heapq.heappush(heap, (new_dist, v))

        if count >= k:
            break

    print(result)

if __name__ == "__main__":
    main()
